    TEST_ASSERT_EQUAL_STRING("url(iG/gITL/j)", run("img", "URL(iG/gITL/j)"));
    TEST_ASSERT_EQUAL_STRING("url(YCF.qNCuYWJwM_pY/aBa.-Jf), radial-gradient(farthest-side at 1554.8% top, #708f6b, #14f33a)", run("img", "url('YCF.qNCuYWJwM_pY/aBa.-Jf'),  RADIAL-GRADIENT(FartHEst-side at 1554.8% TOP, 	 #708f6b, 	 #14F33A)"));
